CREATE TABLE gene(ID_GENE DECIMAL(38,0) NOT NULL, COSMIC_ID_GENE DECIMAL(38,0) DEFAULT(NULL), GENE_SYMBOL VARCHAR NOT NULL, GENOME_VERSION SMALLINT DEFAULT(NULL), FULL_NAME VARCHAR DEFAULT(NULL), CHROMOSOME TINYINT DEFAULT(NULL), CHROM_ARM VARCHAR DEFAULT(NULL), CHROM_BAND VARCHAR DEFAULT(NULL), HGNC_ID DECIMAL(38,0) DEFAULT(NULL), OMIM_ID DECIMAL(38,0) DEFAULT(NULL), ENTREZ_GENE_ID DECIMAL(38,0) DEFAULT(NULL), ENSEMBL_GENE_ID VARCHAR DEFAULT(NULL), ENSEMBL_ID_VERSION SMALLINT DEFAULT(NULL), FROM_DB VARCHAR DEFAULT(NULL), ID_BIOTYPE DECIMAL(38,0) DEFAULT(NULL), "VERSION" SMALLINT DEFAULT(NULL));;
CREATE TABLE transcript(ID_TRANSCRIPT DECIMAL(38,0) NOT NULL, ID_GENE DECIMAL(38,0) NOT NULL, COSMIC_ID_TRANSCRIPT DECIMAL(38,0) DEFAULT(NULL), GENOME_VERSION SMALLINT DEFAULT(NULL), ACCESSION VARCHAR DEFAULT(NULL), ACCESSION_VERSION SMALLINT DEFAULT(NULL), SOURCE VARCHAR DEFAULT(NULL), "VERSION" SMALLINT DEFAULT(NULL), IS_CANONICAL VARCHAR DEFAULT(NULL), ID_BIOTYPE DECIMAL(38,0) DEFAULT(NULL), CCDS_ACCESSION VARCHAR DEFAULT(NULL), REF_SEQ VARCHAR DEFAULT(NULL), FLAGS VARCHAR DEFAULT(NULL));;

